// The server authorizes every operation. Hidden menus are not access control.
const platformAPI=window.bridge;
const $=id=>document.getElementById(id);
const S={me:null,catalog:null,page:'platform-subscriptions',pluginFilter:'free',staffPage:1,q:'',filter:'all',banned:false,generation:0};
const TIERS=['free','bronze','silver','gold','platinum','emerald','ruby'];
const RECIPES={'workspace-snapshot':['workspace.inspect','workspace.report'],'cleanup-preview':['workspace.inspect','cleanup.preview'],'crawl-brief':['crawler.collect','research.export'],'workflow-checkpoints':['workspace.inspect','task.checkpoint','build.verify','task.report']};
const title=v=>String(v||'').replace(/^./,c=>c.toUpperCase());
const money=v=>cents(v)?new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(v/100):'Price unavailable';
const ax=v=>cents(v)?(v/100).toFixed(2):'—';
const dateTime=v=>{const d=new Date(v);return v&&Number.isFinite(d.getTime())?d.toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}):'Not set';};
function node(tag,cls,value){const e=document.createElement(tag);if(cls)e.className=cls;if(value!==undefined)e.textContent=String(value??'');return e;}
function button(value,fn,cls='secondary'){const e=node('button',cls,value);e.type='button';if(fn)e.addEventListener('click',()=>{if(e.dataset.pending==='1')return;e.dataset.pending='1';const before=e.disabled;e.disabled=true;act(fn).finally(()=>{delete e.dataset.pending;if(e.isConnected)e.disabled=before;});});return e;}
function input(type,name,value=''){const e=node('input');e.type=type;e.name=name;e.value=String(value);return e;}
