function readableError(error){const text=String(error?.message||'The operation could not be completed.');for(const [key,value]of Object.entries({bridge_membership_deletion_unavailable:'Bridge account deletion is not connected to your account service yet.',bridge_membership_deletion_unconfirmed:'The account service did not confirm Bridge removal. Sign in again and contact support.',owner_subject_reauth_required:'Sign in again as the owner and complete MFA to use your included access. Owner purchases are blocked.',owner_purchase_unnecessary:'Your owner access already includes this item for free.',manage_subscription_in_portal:'You already have a subscription. Use Manage billing to review or cancel it; a new plan can start after it ends.',subscription_checkout_in_progress:'A subscription checkout is already open. Finish it or wait for it to expire before starting another.',recent_mfa_required:'Sign in again and complete MFA before making this change.',owner_recent_mfa_required:'Sign in again as the owner and complete MFA before publishing.',central_authority_unavailable:'Account-wide changes are not connected yet. No account-wide change was made.',session_revocation_unavailable:'Secure session revocation is unavailable. The reset or deletion was not applied.',legal_version_changed:'The agreements changed. Refresh and review the current version.',insufficient_credits:'Your Axiom balance is too low for this purchase.'}))if(text.includes(key))return value;return text;}
