function parseCents(raw){const m=/^(0|[1-9]\d*)(?:\.(\d{1,2}))?$/.exec(String(raw).trim());if(!m)throw Error('Enter an amount with no more than two decimal places.');const v=Number(m[1])*100+Number((m[2]||'').padEnd(2,'0'));if(!Number.isSafeInteger(v))throw Error('That amount is too large.');return v;}
function dialog(title){const modal=node('dialog','platform-dialog');const h=node('div','platform-dialog-heading');h.append(node('h2','',title));const body=node('div','platform-dialog-body'),footer=node('div','platform-dialog-footer');modal.append(h,body,footer);document.body.append(modal);modal.showModal();const close=()=>{modal.close();modal.remove();};modal.addEventListener('close',()=>modal.remove(),{once:true});return{modal,body,footer,close};}
